def md(df, fmt=None):
    cols = list(df.columns)
    s = "| " + " | ".join(["model"] + cols) + " |\n|" + "---|" * (len(cols) + 1) + "\n"
    for i, r in df.iterrows():
        s += (
            "| "
            + " | ".join(
                [str(i)]
                + [f"{v:.4g}" if isinstance(v, (float, np.floating)) else str(v) for v in r.values]
            )
            + " |\n"
        )
    return s


def full_report(ev, preds, tag, subsets, ref="snaive24", block=7):
    names = [n for n in ORDER if n in preds]
    rep = {}
    rows = {n: ev.metrics(preds[n]) for n in names}
    T = pd.DataFrame(rows).T
    sk = {}
    for n in names:
        sk[n] = {
            "skill_zh_MAE_vs_snaive24": 1 - T.loc[n, "zh_MAE"] / T.loc["snaive24", "zh_MAE"],
            "skill_city_MAE_vs_snaive24": 1 - T.loc[n, "city_MAE"] / T.loc["snaive24", "city_MAE"],
        }
    T = T.join(pd.DataFrame(sk).T)
    rep["overall"] = T
    for sname, mask in subsets.items():
        rep["subset_" + sname] = pd.DataFrame({n: ev.metrics(preds[n], mask) for n in names}).T
    dz, dc = ({}, {})
    for n in names:
        dz[n], dc[n] = ev.daily(preds[n])
    rows = []
    for n in names:
        if n == ref:
            continue
        r = {}
        for lvl, d in (("zh", dz), ("city", dc)):
            m, lo, hi, p = boot_ci(d[n] - d[ref])
            mb, lob, hib, _ = boot_ci(d[n] - d[ref], block=block)
            r.update(
                {
                    f"{lvl}_dMAE": m,
                    f"{lvl}_CI_day": f"[{lo:.3g}, {hi:.3g}]",
                    f"{lvl}_CI_blk{block}": f"[{lob:.3g}, {hib:.3g}]",
                    f"{lvl}_P(better)": p,
                }
            )
        rows.append(pd.Series(r, name=n))
    rep["bootstrap_vs_" + ref] = pd.DataFrame(rows)
    return (rep, dz, dc)


