number = re.compile(r"[-+]?(?:\d*\.)?\d+(?:[eE][-+]?\d+)?")


def parse_tables(path):
    sections = {}
    section = None
    columns = None
    for line in path.splitlines():
        if line.startswith("## "):
            section = line[3:].strip()
            sections[section] = {}
            columns = None
        elif section and line.startswith("|"):
            cells = [x.strip() for x in line.strip("|").split("|")]
            if columns is None:
                columns = cells[1:]
                continue
            if all(re.fullmatch(r"[-: ]+", x) for x in cells):
                continue
            sections[section][cells[0]] = dict(zip(columns, cells[1:]))
    return sections


def numbers(value):
    if isinstance(value, str):
        return [float(x) for x in number.findall(value)]
    return [float(value)]


def reference_comparison(D, out):
    rows = []
    OUT = Path(out)
    for target in ["volume", "occ"]:
        prior = {"pooled_val_MAE": REFERENCE_TABLES[target]["selection"]}
        ev = evaluation(D, target, "val")
        actual = pd.DataFrame(
            {
                p.stem: ev.metrics(np.load(p))
                for p in (OUT / "val" / target).glob("*.npy")
                if p.stem != "scale" and not p.stem.startswith("curves_")
            }
        ).T
        for model, value in prior["pooled_val_MAE"].items():
            got = float(actual.loc[model, "zh_MAE"])
            tol = max(1e-7, abs(value) * 1e-5)
            rows.append(
                dict(
                    target=target,
                    split="val",
                    section="precise_pooled_MAE",
                    model=model,
                    metric="zh_MAE",
                    element=0,
                    prior=value,
                    reproduced=got,
                    difference=got - value,
                    tolerance=tol,
                    within_tolerance=abs(got - value) <= tol,
                )
            )
        for split in ["val", "test"]:
            ev = evaluation(D, target, split)
            days = ev.days
            cal = ev.cal
            pred = {
                p.stem: np.load(p)
                for p in (OUT / split / target).glob("*.npy")
                if p.stem != "scale" and not p.stem.startswith("curves_")
            }
            if split == "val":
                subsets = {
                    "workdays": ((cal.off == 0) & (cal.hol == 0)).values,
                    "weekend_nonhol": ((cal.wk == 1) & (cal.hol == 0)).values,
                    "QuocKhanh_1-7Oct": np.isin(days, np.arange(30, 37)),
                    "TayLich_31Dec-2Jan": np.isin(days, np.arange(121, 124)),
                }
                for i, (a, b) in enumerate(FOLDS, 1):
                    subsets[f"fold{i}_days{a}-{b}"] = (days >= a) & (days <= b)
            else:
                subsets = {
                    "Tet_21-27Jan": np.isin(days, np.arange(142, 149)),
                    "preTet_20Jan": days == 141,
                    "afterTet_28Jan-28Feb": days >= 149,
                    "workdays": ((cal.off == 0) & (cal.hol == 0)).values,
                }
            reports, _, _ = full_report(ev, pred, split, subsets)
            reports["overall"].to_csv(OUT / f"{split}_overall_{target}_from_saved.csv")
            (OUT / f"tables_{split}_{target}_from_saved.md").write_text(
                f"# Locked {target} {split} metrics\n\n"
                + "\n".join("## " + name + "\n" + md(f) for name, f in reports.items()),
                encoding="utf-8",
            )
            previous = parse_tables(REFERENCE_TABLES[target][split])
            for section, models in previous.items():
                for model, metrics in models.items():
                    for metric, text in metrics.items():
                        expected = numbers(text)
                        if not expected:
                            continue
                        try:
                            got = numbers(reports[section].loc[model, metric])
                        except KeyError:
                            got = []
                        for element, value in enumerate(expected):
                            actual_value = got[element] if element < len(got) else np.nan
                            sig = 3 if "CI_" in metric else 4
                            tol = (
                                1e-8
                                if value == 0
                                else 1.1 * 10 ** (np.floor(np.log10(abs(value))) - sig + 1)
                            )
                            rows.append(
                                dict(
                                    target=target,
                                    split=split,
                                    section=section,
                                    model=model,
                                    metric=metric,
                                    element=element,
                                    prior=value,
                                    reproduced=actual_value,
                                    difference=actual_value - value,
                                    tolerance=tol,
                                    within_tolerance=bool(
                                        np.isfinite(actual_value)
                                        and abs(actual_value - value) <= tol
                                    ),
                                )
                            )
    frame = write_table(out, "reproduction_comparison", rows)
    save_json(
        Path(out) / "reproduction_summary.json",
        dict(
            rows=len(frame),
            within_tolerance=int(frame.within_tolerance.sum()),
            failures=int((~frame.within_tolerance).sum()),
        ),
    )
